import{_ as i,o as l,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2023-01-18","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2023-01-18","date":"2023-01-18T00:00:00.000Z","updated":"2023-01-20T00:00:00.000Z","tags":["Ceph","RGW","分布式存储","软件重构","同步策略"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-01-18.md","filePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-01-18.md","lastUpdated":1780460162000}'),r={name:"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-01-18.md"};function o(n,e,s,d,h,u){return l(),a("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>参与者</strong>: Maui, Yehuda, Adam, Matt, Mia 等团队成员。</li><li><strong>日期</strong>: 2023年1月18日。</li><li><strong>主要议题</strong>: <ol><li>可选yield的更新。</li><li>多站点和墓碑缓存的使用。</li><li>多站点和zipper工作的协同。</li><li>同步策略的更新。</li></ol></li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>可选yield的更新</strong>:</p><ul><li>Maui汇报了一个关于<code>create bucket</code>的PR，讨论了文件逐个处理和整体处理两种方法。</li><li>讨论了在服务中增加可选yield的好处，并计划进行性能基准测试。</li></ul></li><li><p><strong>多站点和墓碑缓存的使用</strong>:</p><ul><li>讨论了使用墓碑缓存解决删除对象时间戳问题，但提出缓存不完整的问题。</li><li>讨论了可能的解决方案，包括将缓存移至rados，以及对同步操作的序列化问题。</li></ul></li><li><p><strong>多站点和zipper工作的协同</strong>:</p><ul><li>讨论了将多站点工作与zipper结合实现存储无关复制。</li><li>提出了对现有代码的修改和潜在的时间压力问题。</li></ul></li><li><p><strong>同步策略的更新</strong>:</p><ul><li>讨论了同步策略的需求，包括在桶级别启用或禁用同步，以及跟踪同步状态的问题。</li><li>提出了对现有同步策略的修改和潜在的复杂性问题。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>将可选yield的工作分配给其他团队成员，并计划进行性能基准测试。</li><li>对多站点的墓碑缓存问题进行进一步的研究和讨论。</li><li>对同步策略的需求进行进一步的研究和讨论。</li></ul><h4 id="后续的行动计划" tabindex="-1">后续的行动计划 <a class="header-anchor" href="#后续的行动计划" aria-label="Permalink to &quot;后续的行动计划&quot;">​</a></h4><ul><li>Maui将联系calpash并帮助其加速上手相关工作。</li><li>对多站点的墓碑缓存问题进行进一步研究和讨论。</li><li>对同步策略的需求进行进一步研究和讨论。</li><li>对新的Centos 9和Ubuntu 22的兼容性问题进行进一步的研究和讨论。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>由于基础设施问题，Reef版本的冻结和发布将推迟最多三个月。</li><li>讨论了rgw套件在新版本Centos和Ubuntu上的兼容性问题，并计划组织相关跟踪问题。</li></ul><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><p>会议讨论了Ceph RGW的重构工作，包括可选yield的更新、多站点和墓碑缓存的使用、多站点和zipper工作的协同以及同步策略的更新。团队决定采取一系列行动来解决这些问题，并计划进行进一步的研究和讨论。此外，由于基础设施问题，Reef版本的发布将推迟，为团队提供了额外的时间来稳定和优化相关功能。</p>',13)])])}const _=i(r,[["render",o]]);export{c as __pageData,_ as default};
